import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import api from '../../api';
import NotificationsList from './NotificationsList';

// SPEC/2026-11-25-notificacoes.md (#75): a conta mostra as notificações, marca como lidas e apaga.

vi.mock('../../api', () => ({ default: { get: vi.fn(), put: vi.fn(), delete: vi.fn() } }));
const mocked = api as unknown as Record<'get' | 'put' | 'delete', ReturnType<typeof vi.fn>>;

const unread = { id: 'n1', title: 'Agendamento confirmado', message: 'Seu horário de 02/12 às 10:00 foi confirmado.', type: 'appointment_reminder', is_read: false, created_at: '2026-12-01T11:00:00Z' };
const read = { id: 'n2', title: 'Feriado', message: 'Fechados na sexta.', type: 'system_alert', is_read: true, created_at: '2026-11-30T11:00:00Z' };

beforeEach(() => {
  mocked.get.mockReset();
  mocked.put.mockReset().mockResolvedValue({ data: {} });
  mocked.delete.mockReset().mockResolvedValue({ data: {} });
});

afterEach(cleanup);

describe('NotificationsList', () => {
  it('lista as notificações e conta as não lidas', async () => {
    mocked.get.mockResolvedValue({ data: [unread, read] });
    render(<NotificationsList />);

    expect(await screen.findByText('Seu horário de 02/12 às 10:00 foi confirmado.')).toBeTruthy();
    expect(screen.getAllByTestId('notificacao')).toHaveLength(2);
    expect(screen.getByRole('heading', { name: 'Notificações (1 não lida)' })).toBeTruthy();
    expect(mocked.get).toHaveBeenCalledWith('/notifications');
  });

  it('marca uma como lida e recarrega', async () => {
    mocked.get.mockResolvedValueOnce({ data: [unread] }).mockResolvedValueOnce({ data: [{ ...unread, is_read: true }] });
    render(<NotificationsList />);

    fireEvent.click(await screen.findByText('Marcar como lida'));

    await waitFor(() => expect(mocked.put).toHaveBeenCalledWith('/notifications/n1/read'));
    await waitFor(() => expect(screen.queryByText('Marcar como lida')).toBeNull());
  });

  it('marca todas como lidas', async () => {
    mocked.get.mockResolvedValue({ data: [unread] });
    render(<NotificationsList />);

    fireEvent.click(await screen.findByText('Marcar todas como lidas'));

    await waitFor(() => expect(mocked.put).toHaveBeenCalledWith('/notifications/read-all'));
  });

  it('apaga uma notificação', async () => {
    mocked.get.mockResolvedValueOnce({ data: [unread, read] }).mockResolvedValueOnce({ data: [unread] });
    render(<NotificationsList />);

    fireEvent.click(await screen.findByLabelText('Apagar Feriado'));

    await waitFor(() => expect(mocked.delete).toHaveBeenCalledWith('/notifications/n2'));
    await waitFor(() => expect(screen.getAllByTestId('notificacao')).toHaveLength(1));
  });

  it('mostra a lista vazia', async () => {
    mocked.get.mockResolvedValue({ data: [] });
    render(<NotificationsList />);
    expect(await screen.findByText('Nenhuma notificação por aqui.')).toBeTruthy();
  });

  it('mostra o erro do servidor', async () => {
    mocked.get.mockRejectedValue(new Error('falhou'));
    render(<NotificationsList />);
    expect((await screen.findByRole('alert')).textContent).toBe('Não foi possível carregar as notificações.');
  });
});
import { useCallback, useEffect, useState } from 'react';
import api from '../../api';
import { apiErrorMessage } from '../../utils/apiError';
import styles from './Account.module.css';

// Notificações do usuário logado em "Minha conta" (SPEC/2026-11-25-notificacoes.md, #75).

export type AppNotification = {
  id: string;
  title: string;
  message: string;
  type: string;
  is_read: boolean;
  created_at: string;
};

const formatDate = (iso: string) =>
  new Date(iso).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });

const NotificationsList = () => {
  const [items, setItems] = useState<AppNotification[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    try {
      const response = await api.get<AppNotification[]>('/notifications');
      setItems(Array.isArray(response.data) ? response.data : []);
      setError('');
    } catch (err) {
      setError(apiErrorMessage(err, 'Não foi possível carregar as notificações.'));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const act = async (action: () => Promise<unknown>, fallback: string) => {
    try {
      await action();
      await load();
    } catch (err) {
      setError(apiErrorMessage(err, fallback));
    }
  };

  const unread = items.filter((n) => !n.is_read).length;

  return (
    <section className={styles.card} aria-labelledby="notificacoes-titulo">
      <h2 id="notificacoes-titulo">
        Notificações{unread > 0 && ` (${unread} não ${unread === 1 ? 'lida' : 'lidas'})`}
      </h2>

      {error && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}
      {loading && <p>Carregando...</p>}
      {!loading && !error && items.length === 0 && <p className={styles.hint}>Nenhuma notificação por aqui.</p>}

      {items.length > 0 && (
        <>
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {items.map((n) => (
              <li
                key={n.id}
                data-testid="notificacao"
                style={{ padding: '0.75rem 0', borderBottom: '1px solid var(--color-border)', opacity: n.is_read ? 0.6 : 1 }}
              >
                <strong>{n.title}</strong> <span className={styles.hint}>{formatDate(n.created_at)}</span>
                <p style={{ margin: '0.25rem 0' }}>{n.message}</p>
                {!n.is_read && (
                  <button
                    type="button"
                    onClick={() => act(() => api.put(`/notifications/${n.id}/read`), 'Não foi possível marcar como lida.')}
                  >
                    Marcar como lida
                  </button>
                )}{' '}
                <button
                  type="button"
                  aria-label={`Apagar ${n.title}`}
                  onClick={() => act(() => api.delete(`/notifications/${n.id}`), 'Não foi possível apagar.')}
                >
                  Apagar
                </button>
              </li>
            ))}
          </ul>
          {unread > 0 && (
            <div className={styles.actions}>
              <button
                type="button"
                className={styles.submit}
                onClick={() => act(() => api.put('/notifications/read-all'), 'Não foi possível marcar todas.')}
              >
                Marcar todas como lidas
              </button>
            </div>
          )}
        </>
      )}
    </section>
  );
};

export default NotificationsList;
// @vitest-environment jsdom
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { AxiosError, type AxiosResponse, type InternalAxiosRequestConfig } from 'axios';
import { afterEach, describe, expect, it, vi } from 'vitest';
import PasswordForm from './PasswordForm';

// SPEC/2026-11-22-auth-perfil-senha.md: formulário de troca de senha da página "Minha conta".

const SUCCESS = 'Senha alterada. As outras sessões foram encerradas.';

function http400(detail: string): AxiosError {
  const config = { headers: {} } as InternalAxiosRequestConfig;
  const response = { status: 400, data: { detail }, statusText: '', headers: {}, config } as AxiosResponse;
  return new AxiosError('HTTP 400', AxiosError.ERR_BAD_REQUEST, config, null, response);
}

function fill(current: string, next: string, confirmation = next) {
  fireEvent.change(screen.getByLabelText('Senha atual'), { target: { value: current } });
  fireEvent.change(screen.getByLabelText('Nova senha'), { target: { value: next } });
  fireEvent.change(screen.getByLabelText('Confirme a nova senha'), { target: { value: confirmation } });
  fireEvent.click(screen.getByRole('button', { name: 'Trocar senha' }));
}

const valueOf = (label: string) => (screen.getByLabelText(label) as HTMLInputElement).value;

afterEach(cleanup);

describe('PasswordForm', () => {
  it('troca a senha, mostra a confirmação do backend e limpa os campos', async () => {
    const onChangePassword = vi.fn().mockResolvedValue(SUCCESS);
    render(<PasswordForm onChangePassword={onChangePassword} />);

    fill('senhaAtual1', 'senhaNova2');

    expect(await screen.findByRole('status')).toHaveProperty('textContent', SUCCESS);
    expect(onChangePassword).toHaveBeenCalledWith('senhaAtual1', 'senhaNova2');
    expect([valueOf('Senha atual'), valueOf('Nova senha'), valueOf('Confirme a nova senha')]).toEqual(['', '', '']);
  });

  it.each([
    ['', 'senhaNova2', 'senhaNova2', 'Informe a senha atual'],
    ['senhaAtual1', 'curta1', 'curta1', 'Nova senha deve ter no mínimo 8 caracteres'],
    ['senhaAtual1', 'senhaAtual1', 'senhaAtual1', 'A nova senha precisa ser diferente da atual.'],
    ['senhaAtual1', 'senhaNova2', 'senhaNova3', 'A confirmação não é igual à nova senha'],
  ])('atual=%j nova=%j confirmação=%j: mostra o erro e não envia', async (current, next, confirmation, message) => {
    const onChangePassword = vi.fn();
    render(<PasswordForm onChangePassword={onChangePassword} />);

    fill(current, next, confirmation);

    expect(await screen.findByRole('alert')).toHaveProperty('textContent', message);
    expect(onChangePassword).not.toHaveBeenCalled();
  });

  it('senha atual errada: mostra o erro do backend e mantém os campos', async () => {
    const onChangePassword = vi.fn().mockRejectedValue(http400('Senha atual incorreta.'));
    render(<PasswordForm onChangePassword={onChangePassword} />);

    fill('senhaErrada9', 'senhaNova2');

    expect(await screen.findByRole('alert')).toHaveProperty('textContent', 'Senha atual incorreta.');
    expect(valueOf('Nova senha')).toBe('senhaNova2');
    expect(screen.queryByRole('status')).toBeNull();
  });

  it('os campos são de senha e têm o autocomplete certo', () => {
    render(<PasswordForm onChangePassword={vi.fn()} />);

    expect(screen.getByLabelText('Senha atual').getAttribute('type')).toBe('password');
    expect(screen.getByLabelText('Senha atual').getAttribute('autocomplete')).toBe('current-password');
    expect(screen.getByLabelText('Nova senha').getAttribute('autocomplete')).toBe('new-password');
  });
});
import React, { useState } from 'react';
import { apiErrorMessage } from '../../utils/apiError';
import { validateNewPassword } from '../../utils/profileValidation';
import styles from './Account.module.css';

type Props = {
  /** Troca a senha e devolve a mensagem de confirmação. */
  onChangePassword: (currentPassword: string, newPassword: string) => Promise<string>;
};

const PasswordForm = ({ onChangePassword }: Props) => {
  const [current, setCurrent] = useState('');
  const [next, setNext] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError('');
    setSuccess('');

    const problem = validateNewPassword(current, next, confirmation);
    if (problem) {
      setError(problem);
      return;
    }

    setSaving(true);
    try {
      setSuccess(await onChangePassword(current, next));
      setCurrent('');
      setNext('');
      setConfirmation('');
    } catch (err) {
      setError(apiErrorMessage(err, 'Não foi possível trocar a senha.'));
    } finally {
      setSaving(false);
    }
  };

  return (
    <form className={styles.card} onSubmit={handleSubmit} noValidate aria-labelledby="senha-titulo">
      <h2 id="senha-titulo">Trocar senha</h2>

      <div className={styles.field}>
        <label htmlFor="senha-atual">Senha atual</label>
        <input
          id="senha-atual"
          type="password"
          value={current}
          onChange={(e) => setCurrent(e.target.value)}
          autoComplete="current-password"
        />
      </div>

      <div className={styles.field}>
        <label htmlFor="senha-nova">Nova senha</label>
        <input
          id="senha-nova"
          type="password"
          value={next}
          onChange={(e) => setNext(e.target.value)}
          autoComplete="new-password"
        />
        <span className={styles.hint}>No mínimo 8 caracteres, com pelo menos 1 letra e 1 número.</span>
      </div>

      <div className={styles.field}>
        <label htmlFor="senha-confirmacao">Confirme a nova senha</label>
        <input
          id="senha-confirmacao"
          type="password"
          value={confirmation}
          onChange={(e) => setConfirmation(e.target.value)}
          autoComplete="new-password"
        />
      </div>

      {error && <p className={styles.error} role="alert">{error}</p>}
      {success && <p className={styles.success} role="status">{success}</p>}

      <div className={styles.actions}>
        <button type="submit" className={styles.submit} disabled={saving}>
          {saving ? 'Trocando...' : 'Trocar senha'}
        </button>
      </div>
    </form>
  );
};

export default PasswordForm;
