    ).toEqual({ avatar_url: 'https://a.com/f.png' });
  });

  it('campos apagados viram null', () => {
    expect(profileChanges(USER, { fullName: 'Maria', phone: ' ', avatarUrl: '' })).toEqual({ phone: null });
