650	import React, { useEffect, useRef, useState } from 'react';
651	import type { AccountUser, ProfileChanges } from '../../hooks/useAccount';
652	import { apiErrorMessage } from '../../utils/apiError';
653	import { formatPhone, validateAvatarUrl, validateFullName, validatePhone } from '../../utils/profileValidation';
654	import styles from './Account.module.css';
