656	type Props = {
657	  user: AccountUser;
658	  /** Salva e devolve o usuário como o backend gravou. */
659	  onSave: (changes: ProfileChanges) => Promise<AccountUser | void>;
660	};
661	
662	/** Campos alterados em relação ao usuário salvo, já no formato do backend. */
663	export function profileChanges(
664	  user: AccountUser,
665	  form: { fullName: string; phone: string; avatarUrl: string },
666	): ProfileChanges {
667	  const changes: ProfileChanges = {};
668	  const fullName = form.fullName.trim();
669	  const phone = formatPhone(form.phone) || null;
670	  const avatarUrl = form.avatarUrl.trim() || null;
671	  if (fullName !== user.full_name) changes.full_name = fullName;
672	  if (phone !== user.phone) changes.phone = phone;
673	  if (avatarUrl !== user.avatar_url) changes.avatar_url = avatarUrl;
674	  return changes;
675	}
676	
677	const ProfileForm = ({ user, onSave }: Props) => {
678	  const [fullName, setFullName] = useState(user.full_name);
679	  const [phone, setPhone] = useState(user.phone ?? '');
680	  const [avatarUrl, setAvatarUrl] = useState(user.avatar_url ?? '');
681	  const [error, setError] = useState('');
682	  const [success, setSuccess] = useState('');
683	  const [saving, setSaving] = useState(false);
684	
685	  const showSaved = (saved: AccountUser) => {
686	    setFullName(saved.full_name);
687	    setPhone(saved.phone ?? '');
688	    setAvatarUrl(saved.avatar_url ?? '');
689	  };
690	
691	  // Quando o usuário muda depois da montagem, os campos acompanham. Na montagem os campos já
692	  // começam com ele: rodar aqui apagaria o que a pessoa digitou antes de o efeito rodar.
693	  const shownUser = useRef(user);
694	  useEffect(() => {
695	    if (shownUser.current === user) return;
696	    shownUser.current = user;
697	    showSaved(user);
698	  }, [user]);
699	
700	  const handleSubmit = async (event: React.FormEvent) => {
701	    event.preventDefault();
702	    setError('');
703	    setSuccess('');
704	
705	    const problem = validateFullName(fullName) ?? validatePhone(phone) ?? validateAvatarUrl(avatarUrl);
706	    if (problem) {
707	      setError(problem);
708	      return;
709	    }
710	    const changes = profileChanges(user, { fullName, phone, avatarUrl });
711	    if (Object.keys(changes).length === 0) {
712	      setSuccess('Nada mudou desde o último salvamento.');
713	      return;
714	    }
715	
716	    setSaving(true);
717	    try {
718	      const saved = await onSave(changes);
719	      // Mostra o que o backend gravou (o telefone volta normalizado) junto com a confirmação,
720	      // sem esperar o efeito acima, que roda depois da renderização.
721	      if (saved) showSaved(saved);
722	      setSuccess('Dados salvos.');
723	    } catch (err) {
724	      setError(apiErrorMessage(err, 'Não foi possível salvar seus dados.'));
725	    } finally {
726	      setSaving(false);
727	    }
728	  };
729	
730	  return (
731	    <form className={styles.card} onSubmit={handleSubmit} noValidate aria-labelledby="perfil-titulo">
732	      <h2 id="perfil-titulo">Dados pessoais</h2>
733	
734	      <div className={styles.field}>
735	        <label htmlFor="perfil-nome">Nome</label>
736	        <input
737	          id="perfil-nome"
738	          value={fullName}
739	          onChange={(e) => setFullName(e.target.value)}
740	          autoComplete="name"
741	          maxLength={255}
742	        />
743	      </div>
744	
745	      <div className={styles.field}>
746	        <label htmlFor="perfil-telefone">Telefone</label>
747	        <input
748	          id="perfil-telefone"
749	          type="tel"
750	          value={phone}
751	          onChange={(e) => setPhone(e.target.value)}
752	          autoComplete="tel-national"
753	          placeholder="(91) 99999-0000"
754	        />
755	        <span className={styles.hint}>Com DDD. Deixe em branco para remover.</span>
756	      </div>
757	
758	      <div className={styles.field}>
759	        <label htmlFor="perfil-foto">URL da foto</label>
760	        <input
761	          id="perfil-foto"
762	          type="url"
763	          value={avatarUrl}
764	          onChange={(e) => setAvatarUrl(e.target.value)}
765	          placeholder="https://"
766	        />
767	      </div>
768	
769	      {error && <p className={styles.error} role="alert">{error}</p>}
770	      {success && <p className={styles.success} role="status">{success}</p>}
771	
772	      <div className={styles.actions}>
773	        <button type="submit" className={styles.submit} disabled={saving}>
774	          {saving ? 'Salvando...' : 'Salvar dados'}
775	        </button>
776	      </div>
777	    </form>
778	  );
779	};
