781	export default ProfileForm;
782	// Regras de status do agendamento no painel (SPEC/2026-11-18-status-agendamento.md).
783	
784	export interface AppointmentLike {
785	  status: string;
786	  start_datetime: string;
787	}
788	
789	const FINISHABLE = ['pending', 'confirmed'];
790	
791	/** "Finalizar" só para agendamento pendente ou confirmado que já começou. */
792	export function canFinish(appointment: AppointmentLike, now: Date = new Date()): boolean {
793	  return (
794	    FINISHABLE.includes(appointment.status) &&
795	    new Date(appointment.start_datetime).getTime() <= now.getTime()
796	  );
797	}
798	// Datas do agendamento no fuso da barbearia (SPEC/2026-11-18-agendamento-fuso-horario.md).
799	// Datas são strings "AAAA-MM-DD"; o backend lê horários sem fuso no fuso da barbearia.
800	
801	export const SHOP_TIMEZONE = 'America/Sao_Paulo';
802	export const MAX_DAYS_AHEAD = 30;
803	
804	const parse = (isoDate: string): [number, number, number] => {
805	  const [year, month, day] = isoDate.split('-').map(Number);
806	  return [year, month, day];
807	};
808	
809	/** "Hoje" no fuso da barbearia, e não em UTC como `toISOString()`. */
810	export function shopToday(now: Date = new Date(), timeZone: string = SHOP_TIMEZONE): string {
811	  return new Intl.DateTimeFormat('en-CA', {
812	    timeZone,
813	    year: 'numeric',
814	    month: '2-digit',
815	    day: '2-digit',
816	  }).format(now);
817	}
818	
819	export function addDays(isoDate: string, days: number): string {
820	  const [year, month, day] = parse(isoDate);
821	  return new Date(Date.UTC(year, month - 1, day + days)).toISOString().slice(0, 10);
822	}
823	
824	/** "segunda-feira, 09/11/2026" */
825	export function formatLongDate(isoDate: string): string {
826	  const [year, month, day] = parse(isoDate);
827	  return new Intl.DateTimeFormat('pt-BR', {
828	    timeZone: 'UTC',
829	    weekday: 'long',
830	    day: '2-digit',
831	    month: '2-digit',
832	    year: 'numeric',
833	  }).format(new Date(Date.UTC(year, month - 1, day, 12)));
834	}
835	
836	/** Valor de `start_datetime` enviado à API: sem fuso, lido no fuso da barbearia. */
837	export function toStartDatetime(isoDate: string, time: string): string {
838	  return `${isoDate}T${time}:00`;
839	}
840	import { isAxiosError } from 'axios';
841	
842	type ValidationIssue = { msg?: string };
843	
844	/**
845	 * Mensagem em português para mostrar ao usuário a partir de um erro da API.
846	 * O 422 do FastAPI traz uma lista de problemas ({ msg }), com o prefixo "Value error, "
847	 * nas validações escritas no backend; os outros erros trazem `detail` como texto.
848	 */
849	export function apiErrorMessage(error: unknown, fallback = 'Não foi possível concluir. Tente de novo.'): string {
850	  if (!isAxiosError(error)) return fallback;
851	  if (!error.response) return 'Sem conexão com o servidor. Verifique a internet e tente de novo.';
852	  const detail = (error.response.data as { detail?: unknown } | undefined)?.detail;
853	  if (typeof detail === 'string' && detail) return detail;
854	  if (Array.isArray(detail)) {
855	    const messages = detail
856	      .map((issue: ValidationIssue) => (issue?.msg ?? '').replace(/^Value error, /, ''))
857	      .filter(Boolean);
858	    if (messages.length) return messages.join(' | ');
859	  }
860	  return fallback;
861	}
862	import { AxiosError, type AxiosResponse, type InternalAxiosRequestConfig } from 'axios';
863	
864	// Erros da API como o axios os entrega, para os testes dos componentes e hooks.
865	
866	/** Resposta de erro com o `detail` do FastAPI (texto, ou lista de { msg } no 422). */
867	export function httpError(status: number, detail?: unknown): AxiosError {
868	  const config = { headers: {} } as InternalAxiosRequestConfig;
869	  const data = detail === undefined ? {} : { detail };
870	  const response = { status, data, statusText: '', headers: {}, config } as AxiosResponse;
871	  return new AxiosError(`HTTP ${status}`, AxiosError.ERR_BAD_REQUEST, config, null, response);
872	}
873	
874	/** Falha sem resposta, como a de rede fora do ar. */
875	export function networkError(): AxiosError {
876	  return new AxiosError('Network Error', AxiosError.ERR_NETWORK, { headers: {} } as InternalAxiosRequestConfig);
877	}
878	import axios, { AxiosError, type InternalAxiosRequestConfig } from 'axios';
879	
880	// Em `npm run dev`, sem VITE_API_URL, usa o backend local. O build exige a
881	// variável (ver vite.config.ts), então produção nunca cai neste padrão.
882	const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000/api';
883	
884	export const TOKEN_KEY = 'token';
885	
886	// Rotas cujo 401 não se resolve com um refresh: credenciais erradas no login,
887	// sessão encerrada no próprio refresh, ou o logout (SPEC/2026-11-22-auth-refresh-logout.md).
888	const NO_REFRESH_ROUTES = ['/auth/login', '/auth/refresh', '/auth/logout'];
889	
890	// withCredentials: o refresh token vai num cookie httpOnly que só o navegador conhece.
891	export const api = axios.create({
892	  baseURL: API_URL,
893	  withCredentials: true,
894	});
895	
896	api.interceptors.request.use((config) => {
897	  const token = localStorage.getItem(TOKEN_KEY);
898	  if (token) {
899	    config.headers.Authorization = `Bearer ${token}`;
900	  }
901	  return config;
902	});
903	
904	type RetriableConfig = InternalAxiosRequestConfig & { _refreshed?: boolean };
905	
906	let pendingRefresh: Promise<string> | null = null;
907	
908	/**
909	 * Troca o cookie de refresh por um access token novo e o guarda.
910	 * Vários pedidos que recebem 401 ao mesmo tempo compartilham uma única chamada.
911	 */
912	export function refreshAccessToken(): Promise<string> {
913	  pendingRefresh ??= api
914	    .post('/auth/refresh')
915	    .then((response) => {
916	      const token: string = response.data.access_token;
917	      localStorage.setItem(TOKEN_KEY, token);
918	      return token;
919	    })
920	    .finally(() => {
921	      pendingRefresh = null;
922	    });
923	  return pendingRefresh;
924	}
925	
926	function canRefresh(config: RetriableConfig | undefined): config is RetriableConfig {
927	  if (!config || config._refreshed) return false;
928	  return !NO_REFRESH_ROUTES.some((route) => config.url?.endsWith(route));
929	}
930	
931	api.interceptors.response.use(undefined, async (error: AxiosError) => {
932	  const config = error.config as RetriableConfig | undefined;
933	  if (error.response?.status !== 401 || !canRefresh(config)) {
934	    throw error;
935	  }
936	  config._refreshed = true;
937	  try {
938	    await refreshAccessToken();
939	  } catch {
940	    localStorage.removeItem(TOKEN_KEY);
941	    throw error;
942	  }
943	  return api(config);
944	});
945	
946	/** Encerra a sessão no servidor (revoga o refresh token) e apaga o token local. */
947	export async function logout(): Promise<void> {
948	  try {
949	    await api.post('/auth/logout');
950	  } catch {
951	    // Sem rede ou sessão já encerrada: o token local sai do mesmo jeito.
952	  } finally {
953	    localStorage.removeItem(TOKEN_KEY);
954	  }
955	}
956	
957	export default api;
