// Regras de status do agendamento no painel (SPEC/2026-11-18-status-agendamento.md).

export interface AppointmentLike {
  status: string;
  start_datetime: string;
}

const FINISHABLE = ['pending', 'confirmed'];

/** "Finalizar" só para agendamento pendente ou confirmado que já começou. */
export function canFinish(appointment: AppointmentLike, now: Date = new Date()): boolean {
  return (
    FINISHABLE.includes(appointment.status) &&
    new Date(appointment.start_datetime).getTime() <= now.getTime()
  );
}
// Datas do agendamento no fuso da barbearia (SPEC/2026-11-18-agendamento-fuso-horario.md).
// Datas são strings "AAAA-MM-DD"; o backend lê horários sem fuso no fuso da barbearia.

export const SHOP_TIMEZONE = 'America/Sao_Paulo';
export const MAX_DAYS_AHEAD = 30;

const parse = (isoDate: string): [number, number, number] => {
  const [year, month, day] = isoDate.split('-').map(Number);
  return [year, month, day];
};

/** "Hoje" no fuso da barbearia, e não em UTC como `toISOString()`. */
export function shopToday(now: Date = new Date(), timeZone: string = SHOP_TIMEZONE): string {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(now);
}

export function addDays(isoDate: string, days: number): string {
  const [year, month, day] = parse(isoDate);
  return new Date(Date.UTC(year, month - 1, day + days)).toISOString().slice(0, 10);
}

/** "segunda-feira, 09/11/2026" */
export function formatLongDate(isoDate: string): string {
  const [year, month, day] = parse(isoDate);
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'UTC',
    weekday: 'long',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).format(new Date(Date.UTC(year, month - 1, day, 12)));
}

/** Valor de `start_datetime` enviado à API: sem fuso, lido no fuso da barbearia. */
export function toStartDatetime(isoDate: string, time: string): string {
  return `${isoDate}T${time}:00`;
}
import { isAxiosError } from 'axios';

type ValidationIssue = { msg?: string };

/**
 * Mensagem em português para mostrar ao usuário a partir de um erro da API.
 * O 422 do FastAPI traz uma lista de problemas ({ msg }), com o prefixo "Value error, "
 * nas validações escritas no backend; os outros erros trazem `detail` como texto.
 */
export function apiErrorMessage(error: unknown, fallback = 'Não foi possível concluir. Tente de novo.'): string {
  if (!isAxiosError(error)) return fallback;
  if (!error.response) return 'Sem conexão com o servidor. Verifique a internet e tente de novo.';
  const detail = (error.response.data as { detail?: unknown } | undefined)?.detail;
  if (typeof detail === 'string' && detail) return detail;
  if (Array.isArray(detail)) {
    const messages = detail
      .map((issue: ValidationIssue) => (issue?.msg ?? '').replace(/^Value error, /, ''))
      .filter(Boolean);
    if (messages.length) return messages.join(' | ');
  }
  return fallback;
}
import { AxiosError, type AxiosResponse, type InternalAxiosRequestConfig } from 'axios';

// Erros da API como o axios os entrega, para os testes dos componentes e hooks.

/** Resposta de erro com o `detail` do FastAPI (texto, ou lista de { msg } no 422). */
export function httpError(status: number, detail?: unknown): AxiosError {
  const config = { headers: {} } as InternalAxiosRequestConfig;
  const data = detail === undefined ? {} : { detail };
  const response = { status, data, statusText: '', headers: {}, config } as AxiosResponse;
  return new AxiosError(`HTTP ${status}`, AxiosError.ERR_BAD_REQUEST, config, null, response);
}

/** Falha sem resposta, como a de rede fora do ar. */
export function networkError(): AxiosError {
  return new AxiosError('Network Error', AxiosError.ERR_NETWORK, { headers: {} } as InternalAxiosRequestConfig);
}
import axios, { AxiosError, type InternalAxiosRequestConfig } from 'axios';

// Em `npm run dev`, sem VITE_API_URL, usa o backend local. O build exige a
// variável (ver vite.config.ts), então produção nunca cai neste padrão.
const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000/api';

export const TOKEN_KEY = 'token';

// Rotas cujo 401 não se resolve com um refresh: credenciais erradas no login,
// sessão encerrada no próprio refresh, ou o logout (SPEC/2026-11-22-auth-refresh-logout.md).
const NO_REFRESH_ROUTES = ['/auth/login', '/auth/refresh', '/auth/logout'];

// withCredentials: o refresh token vai num cookie httpOnly que só o navegador conhece.
export const api = axios.create({
  baseURL: API_URL,
  withCredentials: true,
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem(TOKEN_KEY);
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

type RetriableConfig = InternalAxiosRequestConfig & { _refreshed?: boolean };

let pendingRefresh: Promise<string> | null = null;

/**
 * Troca o cookie de refresh por um access token novo e o guarda.
 * Vários pedidos que recebem 401 ao mesmo tempo compartilham uma única chamada.
 */
export function refreshAccessToken(): Promise<string> {
  pendingRefresh ??= api
    .post('/auth/refresh')
    .then((response) => {
      const token: string = response.data.access_token;
      localStorage.setItem(TOKEN_KEY, token);
      return token;
    })
    .finally(() => {
      pendingRefresh = null;
    });
  return pendingRefresh;
}

function canRefresh(config: RetriableConfig | undefined): config is RetriableConfig {
  if (!config || config._refreshed) return false;
  return !NO_REFRESH_ROUTES.some((route) => config.url?.endsWith(route));
}

api.interceptors.response.use(undefined, async (error: AxiosError) => {
  const config = error.config as RetriableConfig | undefined;
  if (error.response?.status !== 401 || !canRefresh(config)) {
    throw error;
  }
  config._refreshed = true;
  try {
    await refreshAccessToken();
  } catch {
    localStorage.removeItem(TOKEN_KEY);
    throw error;
  }
  return api(config);
});

/** Encerra a sessão no servidor (revoga o refresh token) e apaga o token local. */
export async function logout(): Promise<void> {
  try {
    await api.post('/auth/logout');
  } catch {
    // Sem rede ou sessão já encerrada: o token local sai do mesmo jeito.
  } finally {
    localStorage.removeItem(TOKEN_KEY);
  }
}

