/** Campos da criação, já no formato da API. */
export type ServiceInput = Pick<AdminService, 'name' | 'description' | 'price' | 'duration_minutes'>;
/** Alteração parcial: só os campos que mudaram. */
export type ServiceChanges = Partial<ServiceInput & Pick<AdminService, 'is_active'>>;

export type ServicesStatus = 'loading' | 'ready' | 'error';

/** Mesma ordem do backend: alfabética, sem diferenciar maiúsculas. */
function sortByName(services: AdminService[]): AdminService[] {
  return [...services].sort((a, b) => a.name.localeCompare(b.name, 'pt-BR', { sensitivity: 'base' }));
}

export function useAdminServices() {
  const [services, setServices] = useState<AdminService[]>([]);
  const [status, setStatus] = useState<ServicesStatus>('loading');
  const [loadError, setLoadError] = useState('');
  // Mudar o número pede uma nova carga ("Tentar de novo").
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let active = true;
    setStatus('loading');
    api
      .get<AdminService[]>('/services/admin')
      .then((response) => {
        if (!active) return;
        setServices(response.data);
        setStatus('ready');
      })
      .catch((error) => {
        if (!active) return;
        setLoadError(apiErrorMessage(error, 'Não foi possível carregar os serviços.'));
        setStatus('error');
      });
    return () => {
      active = false;
    };
  }, [attempt]);

  const reload = useCallback(() => setAttempt((n) => n + 1), []);

  /** Põe o serviço gravado na lista, no lugar do antigo ou como novo, mantendo a ordem. */
  const store = useCallback((saved: AdminService) => {
    setServices((current) => sortByName([...current.filter((s) => s.id !== saved.id), saved]));
    return saved;
  }, []);

  const createService = useCallback(
    async (input: ServiceInput) => store((await api.post<AdminService>('/services', input)).data),
    [store],
  );

  const updateService = useCallback(
    async (id: string, changes: ServiceChanges) =>
      store((await api.put<AdminService>(`/services/${id}`, changes)).data),
    [store],
  );

  /** O DELETE só desativa (soft delete) e não devolve corpo: a lista marca o serviço. */
  const deactivateService = useCallback(async (id: string) => {
    await api.delete(`/services/${id}`);
    setServices((current) => current.map((s) => (s.id === id ? { ...s, is_active: false } : s)));
  }, []);

  const reactivateService = useCallback(
    (id: string) => updateService(id, { is_active: true }),
    [updateService],
  );

  return {
    services,
    status,
    loadError,
    reload,
    createService,
    updateService,
    deactivateService,
    reactivateService,
  };
}
// @vitest-environment jsdom
import { act, renderHook, waitFor } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import api from '../api';
import { httpError, networkError } from '../testUtils/httpError';
import { useAdminServices, type AdminService } from './useAdminServices';

// SPEC/2026-11-23-painel-servicos.md: carga pela listagem do admin e as ações sobre a API.

vi.mock('../api', () => ({ default: { get: vi.fn(), post: vi.fn(), put: vi.fn(), delete: vi.fn() } }));
type Mock = ReturnType<typeof vi.fn>;
const mocked = api as unknown as { get: Mock; post: Mock; put: Mock; delete: Mock };

const service = (name: string, extra: Partial<AdminService> = {}): AdminService => ({
  id: name.toLowerCase(),
  name,
  description: null,
  price: '30.00',
  duration_minutes: 30,
  is_active: true,
  ...extra,
});

const BARBA = service('Barba');
const CORTE = service('Corte');
const PIGMENTACAO = service('Pigmentação', { is_active: false });

async function loaded(list: AdminService[] = [BARBA, CORTE, PIGMENTACAO]) {
  mocked.get.mockResolvedValue({ data: list });
  const hook = renderHook(() => useAdminServices());
  await waitFor(() => expect(hook.result.current.status).toBe('ready'));
  return hook;
}

const names = (list: AdminService[]) => list.map((s) => s.name);

beforeEach(() => {
  for (const fn of Object.values(mocked)) fn.mockReset();
});

describe('useAdminServices: carga', () => {
  it('usa a listagem do admin, com ativos e desativados', async () => {
    const { result } = await loaded();

    expect(mocked.get).toHaveBeenCalledWith('/services/admin');
    expect(result.current.services).toEqual([BARBA, CORTE, PIGMENTACAO]);
  });

  it('começa carregando', () => {
    mocked.get.mockReturnValue(new Promise(() => {}));
    const { result } = renderHook(() => useAdminServices());

    expect(result.current.status).toBe('loading');
  });

  it('falha na carga mostra a mensagem do backend', async () => {
    mocked.get.mockRejectedValue(httpError(403, 'Acesso restrito a administradores.'));
    const { result } = renderHook(() => useAdminServices());

    await waitFor(() => expect(result.current.status).toBe('error'));

