1	import { useCallback, useEffect, useState } from 'react';
2	import { apiErrorMessage } from '../utils/apiError';
3	
4	// Carga de dados da API com "carregando", erro em português e "Tentar de novo". Usado pelo
5	// painel de serviços (SPEC/2026-11-23-painel-servicos.md) e por Meus agendamentos
6	// (SPEC/2026-11-25-meus-agendamentos.md). `setData` deixa quem usa atualizar a lista depois
7	// de uma ação, sem carregar de novo. `load` precisa ser estável (função do módulo ou
8	// useCallback): uma função nova a cada renderização carregaria de novo a cada renderização.
9	
10	export type LoadStatus = 'loading' | 'ready' | 'error';
11	
12	export function useApiResource<T>(load: () => Promise<T>, initial: T, fallbackError: string) {
13	  const [data, setData] = useState<T>(initial);
14	  const [status, setStatus] = useState<LoadStatus>('loading');
15	  const [loadError, setLoadError] = useState('');
16	  // Mudar o número pede uma nova carga ("Tentar de novo").
17	  const [attempt, setAttempt] = useState(0);
18	
19	  useEffect(() => {
20	    let active = true;
21	    setStatus('loading');
22	    load()
23	      .then((loaded) => {
24	        if (!active) return;
25	        setData(loaded);
26	        setStatus('ready');
27	      })
28	      .catch((error) => {
29	        if (!active) return;
30	        setLoadError(apiErrorMessage(error, fallbackError));
31	        setStatus('error');
32	      });
33	    return () => {
34	      active = false;
35	    };
36	  }, [attempt, load, fallbackError]);
37	
38	  const reload = useCallback(() => setAttempt((n) => n + 1), []);
39	
40	  return { data, setData, status, loadError, reload };
41	}

